    def __init__(self, num_classes=1000):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        x = x.contiguous()
        weight = self.conv1.weight.contiguous()
        bias = self.conv1.bias.contiguous()

        N = x.shape[0]
        output = torch.empty((N, 96, 55, 55), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()

        NUM_TILES = 25  # (55 // 11) ** 2 spatial tiles per (n, oc)
        BLOCK_THREADS = 128  # padded to a multiple of 32 (11x11=121 active lanes, 7 idle)
        OC_PER_BLOCK = 4  # output channels computed per CTA, reusing the staged input patch
        module.launch(
            "conv2d_kernel",
            grid=(NUM_TILES, 96 // OC_PER_BLOCK, N),
            block=(BLOCK_THREADS, 1, 1),
            arguments=[x, weight, bias, output],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return output
